class Wiki:
    def __init__(self):
        self.pages = {}

    def create_page(self, page, author, text):
        if not page or not author or not isinstance(text, str):
            raise ValueError("Invalid page, author, or text")
        if page in self.pages:
            raise WikiError("Page already exists")
        self.pages[page] = {
            'revisions': [(1, text)],
            'authors': {author},
            'history': [(1, text)],
        }

    def edit_page(self, page, author, text):
        if page not in self.pages:
            raise KeyError("Page does not exist")
        if not author or not isinstance(text, str):
            raise ValueError("Invalid author or text")
        if text == self.pages[page]['revisions'][-1][1]:
            raise WikiError("No change in text")
        revision_number = len(self.pages[page]['revisions']) + 1
        self.pages[page]['revisions'].append((revision_number, text))
        self.pages[page]['authors'].add(author)
        self.pages[page]['history'].append((revision_number, text))
        if len(self.pages[page]['history']) > 5:
            self.pages[page]['history'] = self.pages[page]['history'][-5:]

    def get_text(self, page):
        if page not in self.pages:
            raise KeyError("Page does not exist")
        return self.pages[page]['revisions'][-1][1]

    def get_revision_count(self, page):
        if page not in self.pages:
            raise KeyError("Page does not exist")
