class LockerRoom:
    def __init__(self):
        self.lockers = {}
        self.items = {}
        self.takings = 0

    def add_locker(self, locker_id: str, size: str) -> None:
        if not locker_id or size not in ["small", "medium", "large"]:
            raise ValueError("Invalid locker ID or size")
        if locker_id in self.lockers:
            raise LockerError("Locker ID already exists")
        self.lockers[locker_id] = {"size": size, "item": None}

    def store(self, item_id: str, size: str) -> str:
        if not item_id or size not in ["small", "medium", "large"]:
            raise ValueError("Invalid item ID or size")
        if item_id in self.items:
            raise LockerError("Item ID already stored")
        for locker_id, locker in self.lockers.items():
            if locker["size"] == size and locker["item"] is None:
                locker["item"] = item_id
                self.items[item_id] = locker_id
                self.takings += {"small": 200, "medium": 300, "large": 500}[size]
                return locker_id
        raise NoLockerFree("No free locker of the required size")

    def retrieve(self, item_id: str) -> str:
        if item_id not in self.items:
            raise KeyError("Item not found in any locker")
        locker_id = self.items[item_id]
        self.lockers[locker_id]["item"] = None
        del self.items[item_id]
        return locker_id

    def get_locker(self, item_id: str) -> str:
        if item_id not in self.items:
            raise KeyError("Item not found in any locker")
        return self.items[item_id]

    def get_free_lockers(self) -> list[str]:
        return [locker_id for locker_id, locker in self.lockers.items() if locker["item"] is None]

    def get_takings(self) -> int:
        return self.takings
