        if room in self.rooms:
            raise BookingError("Room already exists")
        self.rooms[room] = []

    def book(self, booking_id: str, room: str, slot: int) -> None:
        if room not in self.rooms:
            raise KeyError("Room does not exist")
        if not booking_id or booking_id is None:
            raise ValueError("Booking ID cannot be empty or None")
        if slot < 0:
            raise ValueError("Slot cannot be below 0")
        if booking_id in self.bookings:
            raise BookingError("Booking ID already used")
        if slot in self.rooms[room]:
            raise RoomBusy("Room already booked in that slot")
        self.rooms[room].append(slot)
        self.bookings[booking_id] = (room, slot)

    def get_booking(self, booking_id: str) -> tuple[str, int]:
        if booking_id not in self.bookings:
            raise KeyError("Booking not found")
        return self.bookings[booking_id]

    def get_bookings(self) -> list[str]:
        return list(self.bookings.keys())

    def get_free_rooms(self, slot: int) -> list[str]:
        if slot < 0:
            raise ValueError("Slot cannot be below 0")
        free_rooms = []
        for room, slots in self.rooms.items():
            if slot not in slots:
                free_rooms.append(room)
        return free_rooms

    def get_rooms(self) -> list[str]:
        return list(self.rooms.keys())
