class RaceTelemetry:
    def __init__(self, laps: int):
        if laps <= 0:
            raise ValueError("Laps must be greater than 0")
        self.laps = laps
        self.cars = {}
        self.results = []

    def add_car(self, car_id: str) -> None:
        if not car_id:
            raise ValueError("Car ID cannot be empty")
        if car_id in self.cars:
            raise TelemetryError("Car ID already added")
        self.cars[car_id] = []

    def get_cars(self) -> list[str]:
        return list(self.cars.keys())

    def record_lap(self, car_id: str, lap_time: int) -> None:
        if car_id not in self.cars:
            raise KeyError("Car ID not added")
        if not isinstance(lap_time, int) or lap_time <= 0:
            raise ValueError("Lap time must be a positive integer")
        if len(self.cars[car_id]) == self.laps:
            raise TelemetryError("Car has already finished")
        self.cars[car_id].append(lap_time)

    def get_lap_times(self, car_id: str) -> list[int]:
        if car_id not in self.cars:
            raise KeyError("Car ID not added")
        return self.cars[car_id]

    def get_results(self) -> list[tuple[str, int]]:
        if not self.cars:
            return []
        finished_cars = [(car_id, sum(times)) for car_id, times in self.cars.items() if len(times) == self.laps]
        finished_cars.sort(key=lambda x: x[1])
        points = [10, 6, 4, 3, 2, 1] + [0] * (len(finished_cars) - 6)
        return list(zip([car_id for car_id, _ in finished_cars], points))
