class ReservationError(Exception):
    pass


class NotEnoughSeats(ReservationError):
    pass


class SeatPlanner:
    def __init__(self):
        self.coaches = {}
        self.bookings = {}

    def add_coach(self, coach_id: str, seats: int) -> None:
        if not coach_id:
            raise ValueError("Empty coach id")
        if seats <= 0:
            raise ValueError("Invalid number of seats")
        if coach_id in self.coaches:
            raise ReservationError("Coach already added")
        self.coaches[coach_id] = {'seats': seats, 'limit': seats * 7 // 10, 'reserved': 0}

    def reserve(self, booking_id: str, size: int) -> str:
        if not booking_id:
            raise ValueError("Empty booking id")
        if size <= 0:
            raise ValueError("Invalid group size")
        if booking_id in self.bookings:
            raise ReservationError("Booking already reserved")
        for coach_id, coach in self.coaches.items():
            if coach['reserved'] + size <= coach['limit']:
                self.bookings[booking_id] = (coach_id, size)
                coach['reserved'] += size
                return coach_id
        raise NotEnoughSeats("Not enough seats for the group")

    def move(self, booking_id: str, coach_id: str) -> None:
        if booking_id not in self.bookings:
            raise KeyError("Unknown booking id")
        if coach_id not in self.coaches:
            raise KeyError("Unknown coach id")
        if self.bookings[booking_id][0] == coach_id:
            raise ValueError("Booking already in the target coach")
        coach = self.coaches[self.bookings[booking_id][0]]
        if coach['reserved'] - self.bookings[booking_id][1] + self.coaches[coach_id]['reserved'] + self.bookings[booking_id][1] > self.coaches[coach_id]['limit']:
            raise NotEnoughSeats("Not enough seats for the group in the target coach")
        coach['reserved'] -= self.bookings[booking_id][1]
        self.coaches[coach_id]['reserved'] += self.bookings[booking_id][1]
        self.bookings[booking_id] = (coach_id, self.bookings[booking_id][1])

    def get_booking(self, booking_id: str) -> tuple[str, int]:
        if booking_id not in self.bookings:
            raise KeyError("Unknown booking id")
        return self.bookings[booking_id]

    def get_reserved(self, coach_id: str) -> int:
        if coach_id not in self.coaches:
            raise KeyError("Unknown coach id")
        return self.coaches[coach_id]['reserved']

    def get_available(self, coach_id: str) -> int:
        if coach_id not in self.coaches:
            raise KeyError("Unknown coach id")
        return self.coaches[coach_id]['limit'] - self.coaches[coach_id]['reserved']

    def get_coaches(self) -> list[str]:
        return list(self.coaches.keys())
