        if follower not in self.users or followee not in self.users:
            raise KeyError("Unknown user")
        if follower == followee:
            raise ValueError("Cannot follow yourself")
        if followee in self.followers[follower]:
            raise FeedError("Already following this user")
        self.followers[follower].append(followee)

    def unfollow(self, follower: str, followee: str) -> None:
        if follower not in self.users or followee not in self.users:
            raise KeyError("Unknown user")
